		return false
	end

	if self.bfht ~= other.bfht then
		return false
	end

	if self.rpue ~= other.rpue then
		return false
	end

	if self._rsd ~= other._rsd then
		return false
	end

	if self._rpd ~= other._rpd then
		return false
	end

	if self.nbfb ~= other.nbfb then
