__bundle_register("Features/Combat/Objects/Task", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@class Task
---@field thread thread
---@field identifier string
---@field createdAt number Timestamp when the task was created.
---@field punishable number A window in seconds where the task can be punished.
---@field after number A window in seconds where the task can be executed.
---@field delay function
local Task = {}
Task.__index = Task

---Check if task should block the input.
---@return boolean
Task.blocking = LPH_NO_VIRTUALIZE(function(self)
	if not (coroutine.status(self.thread) ~= "dead") then
		return false
	end

	-- We've exceeded the execution time. Block if we're within the after window.
	if os.clock() >= self:when() then
		return os.clock() <= self:when() + self.after
	end

	---@note: Allow us to do inputs up until a certain amount of time before the task happens.
	return os.clock() >= self:when() - self.punishable
end)

---Cancel task.
Task.cancel = LPH_NO_VIRTUALIZE(function(self)
	if coroutine.status(self.thread) ~= "suspended" then
		return
	end

	task.cancel(self.thread)
end)

---Get when approximately the task will be executed.
---@return number
Task.when = LPH_NO_VIRTUALIZE(function(self)
	return self.createdAt + self.delay()
end)

---Create new Task object.
---@param identifier string
---@param delay function
---@param punishable number
---@param after number
---@param callback function
---@vararg any
---@return Task
Task.new = LPH_NO_VIRTUALIZE(function(identifier, delay, punishable, after, callback, ...)
	local self = setmetatable({}, Task)
	self.identifier = identifier
	self.createdAt = os.clock()
	self.delay = delay
	self.punishable = punishable
	self.after = after
	self.thread = TaskSpawner.delay("Action_" .. identifier, delay, callback, ...)
	self.forced = false

	if not self.punishable or self.punishable <= 0 then
		self.punishable = Configuration.expectOptionValue("DefaultPunishableWindow") or 0.7
	end

	if not self.after or self.after <= 0 then
		self.after = Configuration.expectOptionValue("DefaultAfterWindow") or 0.1
	end

	return self
end)

-- Return Task module.
return Task

end)
__bundle_register("Features/Combat/Objects/SoundDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Game.Latency
local Latency = require("Game/Latency")

---@class SoundDefender: Defender
---@field owner Model? The owner of the part.
---@field sound Sound The sound that we're defending.
---@field part BasePart A part that we can base the position off of.
local SoundDefender = setmetatable({}, { __index = Defender })
SoundDefender.__index = SoundDefender
SoundDefender.__type = "Sound"

-- Services.
local players = game:GetService("Players")

---Check if we're in a valid state to proceed with the action.
---@param self SoundDefender
---@param options ValidationOptions
---@return boolean
SoundDefender.valid = LPH_NO_VIRTUALIZE(function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local function internalNotifyFunction(timing, message)
		if not options.notify then
			return
		end

		return self:notify(timing, message)
	end

	local timing = options.timing
	local action = options.action

	if self.owner and not self:target(self.owner) then
		if not timing.alp or not players.LocalPlayer.Character or self.owner ~= players.LocalPlayer.Character then
			return internalNotifyFunction(timing, "Not a viable target.")
		end
	end

	local character = players.LocalPlayer.Character
	if not character then
		return internalNotifyFunction(timing, "No character found.")
	end

	local hoptions = HitboxOptions.new(self.part, timing)
	hoptions.spredict = false
	hoptions.action = action
	hoptions:ucache()

	if not self:hc(hoptions, timing.duih and RepeatInfo.new(timing, Latency.rdelay(), self:uid(10)) or nil) then
		return internalNotifyFunction(timing, "Not in hitbox.")
	end

	return true
end)

---Repeat conditional.
---@param self SoundDefender
---@param _ RepeatInfo
---@return boolean
SoundDefender.rc = LPH_NO_VIRTUALIZE(function(self, _)
	if not self.sound.IsPlaying then
		return false
	end

	return true
end)

---Process sound playing.
---@param self SoundDefender
SoundDefender.process = LPH_NO_VIRTUALIZE(function(self)
	---@type SoundTiming?
	local timing = self:initial(
		self.owner or self.part,
		SaveManager.ss,
		self.owner and self.owner.Name or self.part.Name,
		tostring(self.sound.SoundId)
	)

	if not timing then
		return
	end

	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return
	end

	if not timing.alp and (players.LocalPlayer.Character and self.owner == players.LocalPlayer.Character) then
		return
	end

	---@note: Clean up previous tasks that are still waiting or suspended because they're in a different track.
	self:clean()
	self.timing = timing

	-- Use module if we need to.
	if timing.umoa then
		return self:module(timing)
	end

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not timing.rpue then
		return self:actions(timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
	self:srpue(self.entity, timing, info)
end)

---Create new SoundDefender object.
---@param sound Sound
---@param part BasePart
---@return SoundDefender
function SoundDefender.new(sound, part)
	local self = setmetatable(Defender.new(), SoundDefender)
	local soundPlayed = Signal.new(sound.Played)

	self.sound = sound
	self.part = part
	self.owner = sound:FindFirstAncestorWhichIsA("Model")
	self.maid:mark(soundPlayed:connect(
		"SoundDefender_OnSoundPlayed",
		LPH_NO_VIRTUALIZE(function()
			self:process()
		end)
	))

	if sound.Playing then
		self:process()
	end

	return self
end

-- Return SoundDefender module.
return SoundDefender

end)
__bundle_register("Features/Combat/Objects/PartDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.Latency
local Latency = require("Game/Latency")

---@class PartDefender: Defender
---@field part BasePart
---@field timing PartTiming
---@field touched boolean Determines whether if we touched the timing in the past.
---@field vuid string Visualizer UID.
local PartDefender = setmetatable({}, { __index = Defender })
PartDefender.__index = PartDefender
PartDefender.__type = "Part"

-- Services.
local players = game:GetService("Players")

---Get CFrame.
---@param self PartDefender
---@return CFrame
PartDefender.cframe = LPH_NO_VIRTUALIZE(function(self)
	return self.timing.uhc and self.part.CFrame or CFrame.new(self.part.Position)
end)

---Check if we're in a valid state to proceed with the action.
---@param self PartDefender
---@param options ValidationOptions
---@return boolean
PartDefender.valid = LPH_NO_VIRTUALIZE(function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local function internalNotifyFunction(timing, message)
		if not options.notify then
			return
		end

		return self:notify(timing, message)
	end

	local timing = options.timing
	local action = options.action

	local character = players.LocalPlayer.Character
	if not character then
		return internalNotifyFunction(timing, "No character found.")
	end

	local hoptions = HitboxOptions.new(self.part, timing)
	hoptions.spredict = false
	hoptions.action = action
	hoptions:ucache()

	if not timing.duih or timing.umoa then
		if not self:hc(hoptions, timing.duih and RepeatInfo.new(timing, Latency.rdelay(), self.vuid) or nil) then
			return internalNotifyFunction(timing, "Not in hitbox.")
		end
	end

	return true
end)

---Update PartDefender object.
---@param self PartDefender
PartDefender.update = LPH_NO_VIRTUALIZE(function(self)
	-- Skip if we're not handling delay until in hitbox or we want to use modules.
	if not self.timing.duih or self.timing.umoa then
		return
	end

	-- Deny updates if we already have actions in the queue.
	if #self.tasks > 0 then
		return
	end

	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end

	local character = localPlayer.Character
	if not character then
		return
	end

	local hb = self.timing.hitbox

	hb = Vector3.new(PP_SCRAMBLE_NUM(hb.X), PP_SCRAMBLE_NUM(hb.Y), PP_SCRAMBLE_NUM(hb.Z))

	-- Get current hitbox state.
	---@note: If we're using PartDefender, why perserve rotation? It's likely wrong or gonna mess us up.
	local touching, cframe = self:hitbox(
		self:cframe(),
		self.timing.fhb,
		self.timing.hso,
		hb,
		{ character },
		self.timing.htype or Enum.PartType.Block
	)

	if cframe then
		self:visualize(
			self.vuid,
			cframe,
			hb,
			touching and Color3.fromHex("#DDF527") or Color3.fromHex("#2765F5"),
			self.timing.htype or Enum.PartType.Block
		)
	end

	-- Deny updates if we're not touching the part.
	if not touching then
		return
	end

	-- Deny updates if the we were touching the part last and we are touching it now.
	if self.touched and touching then
		return
	end

	-- Ok, set the new state.
	self.touched = touching

	-- Clean all previous tasks. Just to be safe. We already check if it's empty... so.
	self:clean()

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not self.timing.rpue then
		return self:actions(self.timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(self.timing, Latency.rdelay(), self:uid(10))
	self:srpue(self.entity, self.timing, info)
end)

---Create new PartDefender object.
---@param part BasePart
---@param timing PartTiming?
---@return PartDefender?
function PartDefender.new(part, timing)
	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return nil
	end

	local okey = nil

	-- Hotfix for now; too lazy to do it the animation way.
	if part.Name:match("VengefulSlash") then
		okey = "VengefulSlashes"
	end

	local self = setmetatable(Defender.new(), PartDefender)
	self.part = part
	self.timing = timing or self:initial(part, SaveManager.ps, nil, okey or part.Name)
	self.touched = false
	self.vuid = self:uid(10)

	-- Handle no timing.
	if not self.timing then
		return nil
	end

	-- Handle module.
	if self.timing.umoa then
		self:module(self.timing)
	end

	-- Handle no hitbox delay.
	if self.timing.umoa or self.timing.duih then
		return self
	end

	local info = RepeatInfo.new(self.timing, Latency.rdelay(), self:uid(10))

	if self.timing.rpue then
		self:srpue(self.entity, self.timing, info)
	else
		self:actions(self.timing)
	end

	-- Return self.
	return self
end

-- Return PartDefender module.
return PartDefender

end)
__bundle_register("Features/Combat/Objects/AnimatorDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.Timings.PlaybackData
local PlaybackData = require("Game/Timings/PlaybackData")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.OriginalStore
local OriginalStore = require("Utility/OriginalStore")

---@module Features.Combat.EntityHistory
local EntityHistory = require("Features/Combat/EntityHistory")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

---@module Game.Latency
local Latency = require("Game/Latency")

---@module GUI.Library
local Library = require("GUI/Library")

---@class AnimatorDefender: Defender
---@field animator Animator
---@field offset number?
---@field entity Model
---@field keyframes Action[]
---@field timing AnimationTiming?
---@field pbdata table<AnimationTrack, PlaybackData> Playback data to be recorded.
---@field rpbdata table<string, PlaybackData> Recorded playback data. Optimization so we don't have to constantly reiterate over recorded data.
---@field manimations table<number, Animation>
---@field track AnimationTrack? Don't be confused. This is the **valid && last** animation track played.
---@field maid Maid This maid is cleaned up after every new animation track. Safe to use for on-animation-track setup.
---@field sct table<AnimationTrack, boolean> Tracks that need to have their speed changed.
---@field tsc table<AnimationTrack, number> Tracks that are saving their last speed.
---@field _trackSeq number Monotonic counter incremented each time self.track is assigned. Used to detect stale deferred checks.
local AnimatorDefender = setmetatable({}, { __index = Defender })
AnimatorDefender.__index = AnimatorDefender
AnimatorDefender.__type = "Animation"

-- Services.
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

-- Constants.
local MAX_REPEAT_TIME = 5.0
local HISTORY_STEPS = 5.0
local PREDICT_FACING_DELTA = 3
-- How long an entity must be clean before the APB flag is lifted.
local APB_FLAG_RESET_WINDOW = 10.0

-- =============================================================================
-- VIAv2 state tables — upvalues shared across all incoming-animation callbacks.
-- =============================================================================

-- Per-entity spam state: [entityName] = { timestamps = {}, permaBlocked = bool }
local _viaSpamState = {}

-- Global animation event ring buffer: list of os.clock() timestamps.
local _viaGlobalLog = {}

-- Per-entity last-anim timestamp for AnimGap filter: [entityName] = os.clock()
local _viaLastAnimTick = {}

---Return or create spam state for a given entity name.
local function _getVIASpamState(name)
	if not _viaSpamState[name] then
		_viaSpamState[name] = { timestamps = {}, permaBlocked = false }
	end
	return _viaSpamState[name]
end

---Append `now` to `list` and prune entries older than `window` seconds.
local function _viaSpamPrune(list, now, window)
	list[#list + 1] = now
	local cutoff = now - window
	while #list > 0 and list[1] < cutoff do
		table.remove(list, 1)
	end
end

---Count currently playing tracks on a Humanoid.
local function _viaCountActiveTracks(humanoid)
	local n = 0
	for _, t in ipairs(humanoid:GetPlayingAnimationTracks()) do
		if t.IsPlaying then n = n + 1 end
	end
	return n
end

-- Known M1/light-attack animation ID fragments (extend as needed).
local _viaM1Fragments = { "LightAttack", "LightAtk", "M1" }

---Returns true if `aid` looks like an M1 animation.
local function _viaIsM1(aid)
	for _, frag in ipairs(_viaM1Fragments) do
		if string.find(aid, frag, 1, true) then return true end
	end
	return false
end

---Is animation stopped? Made into a function for de-duplication.
---@param self AnimatorDefender
---@param track AnimationTrack
---@param timing AnimationTiming
---@param notify boolean? Whether to notify or not.
---@return boolean
AnimatorDefender.stopped = LPH_NO_VIRTUALIZE(function(self, track, timing, notify)
	local function internalNotifyFunction(...)
		if not notify then
			return
		end

		return self:notify(...)
	end

	local overrideData = Library:GetOverrideData(PP_SCRAMBLE_STR(timing.name))
	local rate = (Configuration.expectOptionValue("IgnoreAnimationEndRate") or 0.0)

	if overrideData then
		rate = overrideData.iaer
	end

	if
		(Configuration.expectToggleValue("AllowFailure") or overrideData)
		and not timing.rpue
		and Random.new():NextNumber(1.0, 100.0) <= rate
		and StateListener.cdodge()
	then
		return false, internalNotifyFunction(timing, "Intentionally ignoring animation end to simulate human error.")
	end

	if not timing.iae and not track.IsPlaying then
		return true, internalNotifyFunction(timing, "Animation stopped playing.")
	end

	if timing.iae and not timing.ieae and not track.IsPlaying and track.TimePosition < track.Length then
		return true, internalNotifyFunction(timing, "Animation stopped playing early.")
	end
end)

---Repeat conditional. Extra parameter 'track' added on.
---@param self AnimatorDefender
---@param info RepeatInfo
---@return boolean
AnimatorDefender.rc = LPH_NO_VIRTUALIZE(function(self, info)
	---@note: There are cases where we might not have a track. If it's not handled properly, it will throw an error.
	-- Perhaps, the animation can end and we're handling a different repeat conditional.
	if not info.track then
		return Logger.warn(
			"(%s) Did you forget to pass the track? Or perhaps you forgot to place a hook before using this function.",
			PP_SCRAMBLE_STR(info.timing.name)
		)
	end

	if self:stopped(info.track, info.timing) then
		return false
	end

	if info.timing.iae and os.clock() - info.start >= ((info.timing.mat / 1000) or MAX_REPEAT_TIME) then
		return self:notify(info.timing, "Max animation timeout exceeded.")
	end

	return true
end)

---Run predict facing hitbox check.
---@param self AnimatorDefender
---@param options HitboxOptions
---@return boolean
AnimatorDefender.pfh = LPH_NO_VIRTUALIZE(function(self, options)
	local root = self.entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end

	local localRoot = players.LocalPlayer.Character and players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
	if not localRoot then
		return false
	end

	if not options.timing.ffh then
		local yrate = EntityHistory.yrate(self.entity)
		if not yrate then
			return false
		end

		if math.abs(yrate) < PREDICT_FACING_DELTA then
			return
		end
	end

	local clone = options:clone()
	clone.hcolor = Color3.new(0, 1, 1)
	clone.mcolor = Color3.new(1, 1, 0)
	clone:ucache()

	local result = false
	local store = OriginalStore.new()

	store:run(root, "CFrame", CFrame.lookAt(root.Position, localRoot.Position), function()
		result = self:hc(clone, nil)
	end)

	return result
end)

---Run past hitbox check.
---@param timing Timing
---@param options HitboxOptions
---@return boolean
AnimatorDefender.phd = LPH_NO_VIRTUALIZE(function(self, timing, options)
	for _, cframe in next, EntityHistory.pstepped(self.entity, HISTORY_STEPS, timing.phds) or {} do
		local clone = options:clone()
		clone.cframe = cframe
		clone.hcolor = Color3.new(0.839215, 0.976470, 0.537254)
		clone.mcolor = Color3.new(0.564705, 0, 1)
		clone:ucache()

		if not self:hc(clone, nil) then
			continue
		end

		return true
	end
end)

---Run our facing extrapolation / interpolation.
AnimatorDefender.fpc = LPH_NO_VIRTUALIZE(function(self, timing, options)
	if timing.duih then
		return false
	end

	if (timing.ffh or timing.pfh) and self:pfh(options) then
		return true
	end

	if timing.phd and self:phd(timing, options) then
		return true
	end
end)

---Check if we're in a valid state to proceed with the action.
---@param self AnimatorDefender
---@param options ValidationOptions
---@return boolean
AnimatorDefender.valid = LPH_NO_VIRTUALIZE(function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local timing = options.timing
	local action = options.action

	local function internalNotifyFunction(...)
		if not options.notify then
			return
		end

		return self:notify(...)
	end

	if not self.track then
		return internalNotifyFunction(timing, "No current track.")
	end

	if not self.entity then
		return internalNotifyFunction(timing, "No entity found.")
	end

	local target = self:target(self.entity)
	if not target then
		return internalNotifyFunction(timing, "Not a viable target.")
	end

	local root = self.entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return internalNotifyFunction(timing, "No humanoid root part found.")
	end

	local character = players.LocalPlayer.Character
	if not character then
		return internalNotifyFunction(timing, "No character found.")
	end

	local targetInstance = self.entity:FindFirstChild("Target")

	if
		targetInstance
		and targetInstance.Value ~= character
		and Configuration.expectToggleValue("CheckTargetingValue")
	then
		return internalNotifyFunction(timing, "Not being targeted.")
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return internalNotifyFunction(timing, "No effect replicator found.")
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return internalNotifyFunction(timing, "No effect replicator module found.")
	end

	if
		not timing.imb
		and root:FindFirstChild("MegalodauntBroken")
		and not players:GetPlayerFromCharacter(self.entity)
	then
		return internalNotifyFunction(timing, "Entity is block broken.")
	end

	if self:stopped(self.track, timing, options.notify) then
		return false
	end

	local hoptions = HitboxOptions.new(root, timing)
	hoptions.spredict = not timing.duih and not timing.dp
	hoptions.ptime = self:fsecs(timing)
	hoptions.action = action
	hoptions.entity = self.entity
	hoptions.visualize = options.visualize
	hoptions:ucache()

	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
	info.track = self.track

	local hc = self:hc(hoptions, timing.duih and info or nil)
	if hc then
		return true
	end

	local pc = self:fpc(timing, hoptions)
	if pc then
		return true
	end

	return self:notify(timing, "Not in hitbox.")
end)

---Update keyframe handling.
---@param self AnimatorDefender
AnimatorDefender.update = LPH_NO_VIRTUALIZE(function(self)
	for track, data in next, self.pbdata do
		-- Don't process tracks.
		if not Configuration.expectToggleValue("ShowAnimationVisualizer") then
			self.pbdata[track] = nil
			continue
		end

		-- Check if the track is playing.
		if not track.IsPlaying then
			-- Remove out of 'pbdata' and put it in to the recorded table.
			self.pbdata[track] = nil
			self.rpbdata[tostring(track.Animation.AnimationId)] = data

			-- Continue to next playback data.
			continue
		end

		-- Start tracking the animation's speed.
		data:astrack(track.Speed)
	end

	-- Evaluation-data AP break detection (two-window check).
	if Configuration.expectToggleValue("ValidateIncomingAnimations") then
		for evTrack, ed in next, self._evaluationData do
			local elapsed = tick() - ed.t


			local isKnown = ed.isKnown
			local function maybeClean()
				if isKnown and self.track == evTrack then
					self:clean()
				end
			end

			-- Early window (within 0.05s): check for near-zero WeightCurrent.
			if elapsed <= 0.05 then
				if ed.h then
					maybeClean()
					self._evaluationData[evTrack] = nil
					continue
				end
				if not ed.r then
					local current = evTrack.WeightCurrent
					ed.h = current <= 0.003
					ed.r = true
				end
				if ed.h then
					Logger.warn(
						"(%s) AP break detected (early window, WC=%.6f) from %s.",
						evTrack.Animation.AnimationId,
						evTrack.WeightCurrent,
						self.entity.Name
					)
					maybeClean()
					self._evaluationData[evTrack] = nil
				end

			-- Late window (after 0.05s): check for de-weighted animation.
			elseif elapsed > 0.05 then
				if ed.g or ed.h then
					maybeClean()
					self._evaluationData[evTrack] = nil
					continue
				end
				if not ed.c then
					local target = evTrack.WeightTarget
					local current = evTrack.WeightCurrent
					ed.g = current <= target * 0.02 and current <= 0.01
					ed.c = true
				end
				if ed.g then
					Logger.warn(
						"(%s) AP break detected (late window, WC=%.6f, WT=%.4f) from %s.",
						evTrack.Animation.AnimationId,
						evTrack.WeightCurrent,
						evTrack.WeightTarget,
						self.entity.Name
					)
					maybeClean()
					self._evaluationData[evTrack] = nil
					continue
				end
				-- Both windows evaluated, no AP break detected. Remove entry.
				self._evaluationData[evTrack] = nil
			end
		end
	end

	if not Configuration.expectToggleValue("AnimationSpeedChanger") then
		return
	end

	-- Animation speed changer.
	local min = Configuration.expectOptionValue("AnimationSpeedMinimum") or 1.0
	local max = Configuration.expectOptionValue("AnimationSpeedMaximum") or 1.3
	local rng = Random.new()

	for track, _ in next, self.sct do
		if not track.IsPlaying then
			self.sct[track] = nil
			self.tsc[track] = nil
			self.multiplier[track] = nil
			continue
		end

		if self.tsc[track] == tostring(track.Speed) then
			continue
		end

		local mode = rng:NextInteger(1, 2)
		local generated = nil

		if not self.multiplier[track] and not Configuration.expectToggleValue("SwitchBetweenSpeeds") then
			generated = rng:NextNumber(min, max)
		end

		if not self.multiplier[track] and Configuration.expectToggleValue("SwitchBetweenSpeeds") then
			generated = mode == 1 and min or max
		end

		if not self.multiplier[track] and generated then
			self.multiplier[track] = generated
		end

		local multiplier = self.multiplier[track]
		if not multiplier then
			continue
		end

		if multiplier == 1.0 then
			continue
		end

		local adjusted = track.Speed * multiplier

		track:AdjustSpeed(adjusted)

		self.tsc[track] = tostring(track.Speed)
	end
end)

---Virtualized processing checks.
---@param track AnimationTrack
---@return boolean
function AnimatorDefender:pvalidate(track)
	if Configuration.expectToggleValue("ValidateIncomingAnimations") then
		if track.Priority == Enum.AnimationPriority.Core then
			return false
		end

		local isComingFromPlayer = players:GetPlayerFromCharacter(self.entity)

		-- Only run AP breaking checks on known animations in the timing database.
		local isKnownAnimation = isComingFromPlayer and SaveManager.as:index(tostring(track.Animation.AnimationId)) ~= nil

		-- Charged attacks freeze at speed 0 during windup with WT > 1.0 to override.
		if isKnownAnimation and math.abs(track.Speed) < 0.05 then
			-- WT > 1.0: legit windup (charged attack), poll until speed changes.
			if track.WeightTarget > 1.0 then
				local myTrack = track
				local myAid = tostring(track.Animation.AnimationId)
				task.spawn(function()
					local start = os.clock()
					while os.clock() - start < 0.50 do
						task.wait(0.02)
						if math.abs(myTrack.Speed) >= 0.05 then
							if not self:pvalidate(myTrack) then return end
							self:processValidated(myTrack, myAid, 99)
							return
						end
					end
				end)
				return false
			end

			-- WT <= 1.0: no legit animation does this, reject.
			return false
		end

		if isKnownAnimation and math.abs(track.Speed) > 2 then
			Logger.warn(
				"(%s) Animation is being skipped from player %s because they're likely AP breaking. (Speed=%.2f)",
				track.Animation.AnimationId,
				self.entity.Name,
				track.Speed
			)
			return false
		end

		if isComingFromPlayer and self.manimations[track.Animation.AnimationId] ~= nil then
			Logger.warn(
				"(%s) Animation %s is being skipped from player %s because they're likely AP breaking.",
				self.manimations[track.Animation.AnimationId].Name,
				track.Animation.AnimationId,
				self.entity.Name
			)

			return false
		end
	end

	return true
end

---Animation speed changer.
---@param self AnimatorDefender
---@param track AnimationTrack
AnimatorDefender.asc = LPH_NO_VIRTUALIZE(function(self, track)
	if not Configuration.expectToggleValue("AnimationSpeedChanger") then
		return
	end

	if
		Configuration.expectToggleValue("LimitToAPAnimations")
		and not SaveManager.as:index(tostring(track.Animation.AnimationId))
	then
		return
	end

	self.sct[track] = true
end)

---Compute AP break profile from collected samples.
---@param self AnimatorDefender
function AnimatorDefender:_apbComputeProfile()
	if #self._apbSamples < 3 then return end

	local minS, maxS = math.huge, -math.huge
	local minW, maxW = math.huge, -math.huge

	for _, s in next, self._apbSamples do
		if s.speed < minS then minS = s.speed end
		if s.speed > maxS then maxS = s.speed end
		if s.weightCurrent < minW then minW = s.weightCurrent end
		if s.weightCurrent > maxW then maxW = s.weightCurrent end
	end

	self._apbProfile = {
		minSpeed = math.max(0, minS - 0.5),
		maxSpeed = maxS + 0.5,
		minWC = math.max(0, minW - 0.01),
		maxWC = math.min(maxW + 0.05, 0.15),
	}

	Logger.warn(
		"(%s) AP break profile updated. (%d samples, Speed=%.2f-%.2f, WC=%.4f-%.4f)",
		self.entity.Name,
		#self._apbSamples,
		self._apbProfile.minSpeed,
		self._apbProfile.maxSpeed,
		self._apbProfile.minWC,
		self._apbProfile.maxWC
	)
end

---Process animation track.
---@todo: AP telemetry - aswell as tracking effects that are added with timestamps and current ping to that list.
---@param self AnimatorDefender
---@param track AnimationTrack
AnimatorDefender.process = LPH_NO_VIRTUALIZE(function(self, track)
	local isLocalPlayer = players.LocalPlayer.Character and self.entity == players.LocalPlayer.Character

	if isLocalPlayer then
		self:asc(track)

		-- Log local player animations to builder logger.
		local aid = tostring(track.Animation.AnimationId)
		self:initial(self.entity, SaveManager.as, self.entity.Name, aid)
		return
	end

	-- AP break protection: background detection + blocking gate.
	local aid = tostring(track.Animation.AnimationId)
	local isPlayer = players:GetPlayerFromCharacter(self.entity)
	local isKnownAnimation = isPlayer and SaveManager.as:index(aid) ~= nil

	if Configuration.expectToggleValue("ValidateIncomingAnimations") then
		-- Reject known attacks playing at Idle or Movement priority (priority spoofing AP break technique).
		if isKnownAnimation and (track.Priority == Enum.AnimationPriority.Idle or track.Priority == Enum.AnimationPriority.Movement) then
			Logger.warn(
				"(%s) Animation from %s rejected — known attack playing at %s priority (priority spoofing).",
				aid,
				self.entity.Name,
				tostring(track.Priority)
			)
			return
		end

		-- Reject known attacks with reduced weight target (weight spoofing AP break technique).
		-- WT >= 1.0 is legit (charged attacks use WT=2.0 to override).
		if isKnownAnimation and track.WeightTarget < 1.0 then
			Logger.warn(
				"(%s) Animation from %s rejected — known attack with WeightTarget=%.4f (weight spoofing).",
				aid,
				self.entity.Name,
				track.WeightTarget
			)
			return
		end

		if isKnownAnimation then
			-- FIX: Store isKnown alongside the evaluation entry so the update() loop
			-- can guard clean() calls without re-querying SaveManager each frame.
			self._evaluationData[track] = { t = tick(), isKnown = true }

			local now = os.clock()

			-- Frequency-based detection.
			table.insert(self._apbAnimTimestamps, now)

			-- Clean old timestamps (keep last 2 seconds).
			local cutoff = now - 2
			local firstValidIdx = 0
			for i, t in next, self._apbAnimTimestamps do
				if t > cutoff then
					firstValidIdx = i
					break
				end
			end

			if firstValidIdx > 1 then
				local newTimestamps = {}
				for i = firstValidIdx, #self._apbAnimTimestamps do
					table.insert(newTimestamps, self._apbAnimTimestamps[i])
				end
				self._apbAnimTimestamps = newTimestamps
			elseif firstValidIdx == 0 and #self._apbAnimTimestamps > 0 then
				self._apbAnimTimestamps = {}
			end

			-- Count animations in the last 1 second.
			local recentCount = 0
			for _, t in next, self._apbAnimTimestamps do
				if now - t <= 1 then
					recentCount = recentCount + 1
				end
			end

			-- Frequency spike: flag entity.
			if recentCount >= 6 then
				if not self._apbFlagged then
					self._apbFlagged = true
					self._apbFlaggedAt = os.clock()
					Logger.warn("(%s) Flagged as AP breaker by frequency detection. (%d animations in 1s)", self.entity.Name, recentCount)
				end

				self._apbLastLow = now
			end

			-- Counter window: reset if no low-weight detected in 5 seconds.
			if self._apbLowCount > 0 and now - self._apbLastLow > 5 then
				self._apbLowCount = 0
			end

			if self._apbFlagged and os.clock() - self._apbFlaggedAt > APB_FLAG_RESET_WINDOW then
				self._apbFlagged = false
				self._apbLowCount = 0
				self._apbAnimTimestamps = {}
				self._apbProfile = nil
				self._apbSamples = {}
				Logger.warn("(%s) APB flag lifted after clean window.", self.entity.Name)
			end

			-- Background WeightCurrent check (non-blocking detection).
			if not self._apbFlagged then
				task.spawn(function()
					task.wait(0.02)
					if track.WeightCurrent < 0.20 then
						self._apbLowCount = self._apbLowCount + 1
						self._apbLastLow = os.clock()

						if self._apbLowCount >= 5 then
							self._apbFlagged = true
							self._apbFlaggedAt = os.clock()
						end
					end
				end)
			end

			-- FadeTime inference check.
			-- Palantir-style AP break: WeightTarget=0.1, FadeTime=0.5.
			-- A legit animation (FadeTime~0.05s default) is fully weighted well before 0.05s.
			-- An AP break animation (FadeTime=0.5) only reaches ~10% of WeightTarget at 0.05s.
			do
				local capturedTrack = track
				local capturedAid = aid
				local capturedSeq = self._trackSeq
				task.delay(0.05, function()
					if not capturedTrack.IsPlaying then return end
					local wt = capturedTrack.WeightTarget
					local wc = capturedTrack.WeightCurrent
					if wt > 0 and wc < wt * 0.5 then
						Logger.warn(
							"(%s) Animation from %s rejected — FadeTime AP break. (WC=%.4f / WT=%.4f at t=0.05s)",
							capturedAid, self.entity.Name, wc, wt
						)
						if self.track == capturedTrack and self._trackSeq == capturedSeq then
							self:clean()
						end
						self._evaluationData[capturedTrack] = nil
					end
				end)
			end

			-- Exempt legit windups: speed 0 + WT > 1.0 (charged attacks).
			if math.abs(track.Speed) < 0.05 and track.WeightTarget > 1.0 then
				local myTrack = track
				local myAid = aid
				task.spawn(function()
					local start = os.clock()
					while os.clock() - start < 0.50 do
						task.wait(0.02)
						if math.abs(myTrack.Speed) >= 0.05 then
							if not self:pvalidate(myTrack) then return end
							self:processValidated(myTrack, myAid, 99)
							return
						end
					end
				end)
				return
			end

			-- Blocking gate for flagged entities.
			if self._apbFlagged then
				task.wait(0.02)
				local wc = track.WeightCurrent
				local speed = math.abs(track.Speed)

				-- Profile-based rejection.
				if self._apbProfile then
					local p = self._apbProfile
					if speed >= p.minSpeed and speed <= p.maxSpeed
						and wc >= p.minWC and wc <= p.maxWC then
						-- Collect sample for continuous learning.
						table.insert(self._apbSamples, { speed = speed, weightCurrent = wc })
						self:_apbComputeProfile()
						return
					end
				end

				-- Standard WC threshold rejection.
				if wc < 0.15 then
					table.insert(self._apbSamples, { speed = speed, weightCurrent = wc })
					self:_apbComputeProfile()

					Logger.warn(
						"(%s) Animation from %s rejected by AP break protection. (WeightCurrent=%.6f)",
						track.Animation.AnimationId,
						self.entity.Name,
						wc
					)
					return
				end

				-- Schedule judge at 0.06s. Capture per-callback locals — no shared state.
				local myTrack = track
				local myAid = aid
				local mySeq = self._trackSeq

				task.delay(0.06, function()
					-- Judge: verify animation is still alive and progressing.
					if not myTrack.IsPlaying and myTrack.TimePosition < myTrack.Length then
						Logger.warn(
							"(%s) Animation from %s rejected by ramp gate. (IsPlaying=%s, WC=%.4f, TimePos=%.3f)",
							myTrack.Animation.AnimationId,
							self.entity.Name,
							tostring(myTrack.IsPlaying),
							myTrack.WeightCurrent,
							myTrack.TimePosition
						)
						return
					end

					if myTrack.IsPlaying and myTrack.WeightCurrent < 0.50 then
						Logger.warn(
							"(%s) Animation from %s rejected by ramp gate. (IsPlaying=%s, WC=%.4f, TimePos=%.3f)",
							myTrack.Animation.AnimationId,
							self.entity.Name,
							tostring(myTrack.IsPlaying),
							myTrack.WeightCurrent,
							myTrack.TimePosition
						)
						return
					end

					-- Passed judge. Process with timing compensation.
					if self._trackSeq ~= mySeq then
						return
					end

					if not self:pvalidate(myTrack) then
						return
					end

					self:processValidated(myTrack, myAid, 0.08)
				end)
				return
			end
		end
	end

	-- ValidateIncomingAnimations V2: per-filter toggleable protection.
	-- Each filter maps to a visible UI toggle + optional slider threshold.
	-- Independent of V1 — both can run simultaneously.
	-- Settings sourced from Pr2.json — see config key map in VIAv2 state tables block.
	if Configuration.expectToggleValue("ValidateIncomingAnimationsV2") and isPlayer then
		local entityName = self.entity.Name
		local now        = os.clock()

		-- -----------------------------------------------------------------------
		-- AnimationEnd suppression.
		-- ForceIgnoreAnimEnd: hard-suppress all AnimEnd events on this track.
		-- ForceIgnoreM1Only:  suppress only for M1/light-attack animations.
		-- IgnoreAnimEnd:      soft — suppress if the track is still playing at event time.
		-- Sets self._suppressAnimEnd[track] = true; processValidated checks this flag.
		-- -----------------------------------------------------------------------
		local suppressAnimEnd = false
		if Configuration.expectToggleValue("VIAv2ForceIgnoreAnimEnd") then
			suppressAnimEnd = true
		elseif Configuration.expectToggleValue("VIAv2ForceIgnoreM1Only") and _viaIsM1(aid) then
			suppressAnimEnd = true
		elseif Configuration.expectToggleValue("VIAv2IgnoreAnimEnd") and track.IsPlaying then
			suppressAnimEnd = true
		end
		if suppressAnimEnd then
			self._suppressAnimEnd = self._suppressAnimEnd or {}
			self._suppressAnimEnd[track] = true
		end

		-- -----------------------------------------------------------------------
		-- Filter: Idle Priority
		-- Reject known attacks playing at Idle priority (priority spoofing).
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterIdlePriority") then
			if isKnownAnimation and track.Priority == Enum.AnimationPriority.Idle then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — Idle priority spoofing.",
					aid, entityName
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Movement Priority
		-- Reject known attacks playing at Movement priority (priority spoofing).
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterMovementPriority") then
			if isKnownAnimation and track.Priority == Enum.AnimationPriority.Movement then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — Movement priority spoofing.",
					aid, entityName
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Core Priority
		-- Reject known attacks at Core priority (highest tier, rarely legit).
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterCorePriority") then
			if isKnownAnimation and track.Priority == Enum.AnimationPriority.Core then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — Core priority AP break.",
					aid, entityName
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Priority Hiding (Action4)
		-- Reject known attacks at Action4 — outside the range most anti-AP systems scan.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterPriorityHiding") then
			if isKnownAnimation and track.Priority == Enum.AnimationPriority.Action4 then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — Action4 priority hiding.",
					aid, entityName
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Action Priority (explicit)
		-- Reject known attacks at plain Action priority.
		-- Useful when the breaker stays in the expected tier but spikes other params.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterActionPriority") then
			if isKnownAnimation and track.Priority == Enum.AnimationPriority.Action then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — Action priority (explicit filter).",
					aid, entityName
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: WeightTarget threshold
		-- Reject if WeightTarget < VIAv2MinWT. Default from Pr2.json: 0.4.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterWT") then
			local minWT = Configuration.expectOptionValue("VIAv2MinWT") or 0.4
			if isKnownAnimation and track.WeightTarget < minWT then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — WeightTarget=%.4f < min=%.4f.",
					aid, entityName, track.WeightTarget, minWT
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Speed threshold
		-- Reject if |Speed| > VIAv2MaxSpeed. Default from Pr2.json: 10.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterSpeed") then
			local maxSpeed = Configuration.expectOptionValue("VIAv2MaxSpeed") or 10
			if isKnownAnimation and math.abs(track.Speed) > maxSpeed then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — Speed=%.2f > max=%.2f.",
					aid, entityName, math.abs(track.Speed), maxSpeed
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Animation Gap
		-- Reject if the gap between consecutive known animations from this entity
		-- is smaller than VIAv2MinAnimGap seconds. Default: 0.05s.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterAnimGap") then
			if isKnownAnimation then
				local minGap   = Configuration.expectOptionValue("VIAv2MinAnimGap") or 0.05
				local lastTick = _viaLastAnimTick[entityName]
				if lastTick and (now - lastTick) < minGap then
					Logger.warn(
						"[VIAv2] (%s) Rejected from %s — AnimGap=%.3fs < min=%.3fs.",
						aid, entityName, now - lastTick, minGap
					)
					-- Update timestamp even on reject so the window keeps sliding.
					_viaLastAnimTick[entityName] = now
					return
				end
				_viaLastAnimTick[entityName] = now
			end
		else
			-- Track gap unconditionally so Spam/EarlyStop have accurate recency data.
			if isKnownAnimation then
				_viaLastAnimTick[entityName] = now
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Max Active Timings
		-- Reject if the entity has more than VIAv2MaxActiveTimings playing tracks.
		-- Default from Pr2.json: 4.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterMaxActiveTimings") then
			if isKnownAnimation then
				local humanoid = self.entity:FindFirstChildOfClass("Humanoid")
				if humanoid then
					local maxActive   = Configuration.expectOptionValue("VIAv2MaxActiveTimings") or 4
					local activeCount = _viaCountActiveTracks(humanoid)
					if activeCount > maxActive then
						Logger.warn(
							"[VIAv2] (%s) Rejected from %s — ActiveTimings=%d > max=%d.",
							aid, entityName, activeCount, maxActive
						)
						return
					end
				end
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Per-entity Spam
		-- Reject if this entity fires more than VIAv2SpamThreshold known animations
		-- within VIAv2SpamWindow seconds. Defaults: threshold=2, window=1s.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterSpam") then
			if isKnownAnimation then
				local spamState  = _getVIASpamState(entityName)
				local window     = Configuration.expectOptionValue("VIAv2SpamWindow")    or 1
				local threshold  = Configuration.expectOptionValue("VIAv2SpamThreshold") or 2

				_viaSpamPrune(spamState.timestamps, now, window)

				if #spamState.timestamps > threshold then
					if Configuration.expectToggleValue("VIAv2FilterSpamPermaBlock") then
						spamState.permaBlocked = true
					end
					Logger.warn(
						"[VIAv2] (%s) Rejected from %s — Spam (%d events in %.1fs window).",
						aid, entityName, #spamState.timestamps, window
					)
					return
				end
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Perma-Block
		-- Once an entity has been flagged for spam, block all subsequent known
		-- animations from them for the duration of the session.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterSpamPermaBlock") then
			local spamState = _getVIASpamState(entityName)
			if spamState.permaBlocked and isKnownAnimation then
				Logger.warn(
					"[VIAv2] (%s) Rejected from %s — entity is perma-blocked (previous spam detected).",
					aid, entityName
				)
				return
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: Global Spam
		-- Reject if total known-animation events across ALL entities exceed
		-- VIAv2GlobalSpamThreshold within VIAv2GlobalSpamWindow seconds.
		-- Catches coordinated multi-player AP break spam. Defaults: threshold=4, window=2s.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterGlobalSpam") then
			if isKnownAnimation then
				local globalWindow    = Configuration.expectOptionValue("VIAv2GlobalSpamWindow")    or 2
				local globalThreshold = Configuration.expectOptionValue("VIAv2GlobalSpamThreshold") or 4

				_viaSpamPrune(_viaGlobalLog, now, globalWindow)

				if #_viaGlobalLog > globalThreshold then
					Logger.warn(
						"[VIAv2] (%s) Rejected from %s — GlobalSpam (%d events in %.1fs window).",
						aid, entityName, #_viaGlobalLog, globalWindow
					)
					return
				end
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: HighFade (async — samples WeightCurrent after VIAv2FadetimeWindow ms)
		-- Rejects animations ramping too slowly toward their WeightTarget.
		-- Interpretation: reject if WC < WT / VIAv2HighFadeThreshold at sample time.
		--   threshold=6 → WC must be >= WT/6 (~16.7%) — tighter window, looser ratio.
		--   Replaces old FadetimeRatio=0.5 with the json-native HighFadeThreshold param.
		--   Old VIAv2FadetimeRatio slider still works for V1 compat; this drives V2.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterFadetime") then
			if isKnownAnimation then
				local windowMs    = Configuration.expectOptionValue("VIAv2FadetimeWindow")    or 25
				local threshold   = Configuration.expectOptionValue("VIAv2HighFadeThreshold") or 6
				local capturedTrack = track
				local capturedAid   = aid
				local capturedSeq   = self._trackSeq
				if threshold <= 0 then threshold = 1 end
				task.delay(windowMs / 1000, function()
					if not capturedTrack.IsPlaying then return end
					local wt = capturedTrack.WeightTarget
					local wc = capturedTrack.WeightCurrent
					if wt > 0 and wc < wt / threshold then
						Logger.warn(
							"[VIAv2] (%s) Rejected from %s — HighFade AP break (WC=%.4f / WT=%.4f at t=%dms, limit=WT/%.0f).",
							capturedAid, entityName, wc, wt, windowMs, threshold
						)
						if self.track == capturedTrack and self._trackSeq == capturedSeq then
							self:clean()
						end
						self._evaluationData[capturedTrack] = nil
					end
				end)
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: AnimLength / MinLength
		-- Reject if the track stops before VIAv2MinLengthMs milliseconds (short-burst).
		-- VIAv2MinLengthMs=0 disables (json default). Set > 0 to activate.
		-- The existing VIAv2MaxLength slider (old Length filter) still runs below.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterLength") then
			if isKnownAnimation then
				-- New: MinLength guard (from Pr2.json FilterMinLengthMs).
				local minLenMs      = Configuration.expectOptionValue("VIAv2MinLengthMs") or 0
				-- Legacy: MaxLength guard (original behavior).
				local maxLen        = (Configuration.expectOptionValue("VIAv2MaxLength") or 300) / 1000
				local capturedTrack = track
				local capturedAid   = aid
				local capturedSeq   = self._trackSeq

				if minLenMs > 0 then
					task.spawn(function()
						task.wait(minLenMs / 1000)
						if capturedTrack.IsPlaying then return end
						Logger.warn(
							"[VIAv2] (%s) Rejected from %s — track stopped before %dms (MinLength AP break).",
							capturedAid, entityName, minLenMs
						)
						if self._trackSeq == capturedSeq and self.track == capturedTrack then
							self:clean()
						end
					end)
				end

				task.spawn(function()
					task.wait(maxLen)
					if capturedTrack.IsPlaying then return end
					Logger.warn(
						"[VIAv2] (%s) Rejected from %s — track stopped before %.0fms (short-burst AP break).",
						capturedAid, entityName, maxLen * 1000
					)
					if self._trackSeq == capturedSeq and self.track == capturedTrack then
						self:clean()
					end
				end)
			end
		end

		-- -----------------------------------------------------------------------
		-- Filter: EarlyStop
		-- Distinct from AnimLength: catches tracks forcibly killed by the AP breaker
		-- (AnimationEnd fires early) rather than tracks that naturally run short.
		-- Listens on track.Ended; if elapsed < VIAv2EarlyStopTime ms → reject.
		-- Default from Pr2.json: 100ms.
		-- -----------------------------------------------------------------------
		if Configuration.expectToggleValue("VIAv2FilterEarlyStop") then
			if isKnownAnimation then
				local earlyMs       = Configuration.expectOptionValue("VIAv2EarlyStopTime") or 100
				local startedAt     = now
				local capturedTrack = track
				local capturedAid   = aid
				local capturedSeq   = self._trackSeq

				local endConn
				endConn = capturedTrack.Ended:Connect(function()
					endConn:Disconnect()
					local elapsed = (os.clock() - startedAt) * 1000
					if elapsed < earlyMs then
						Logger.warn(
							"[VIAv2] (%s) Rejected from %s — EarlyStop after %.1fms (threshold=%dms).",
							capturedAid, entityName, elapsed, earlyMs
						)
						if self._trackSeq == capturedSeq and self.track == capturedTrack then
							self:clean()
						end
						self._evaluationData[capturedTrack] = nil
					end
				end)
			end
		end

	end

	if not self:pvalidate(track) then
		return
	end

	-- Process (non-flagged entities only — flagged entities are handled by the judge above).
	self:processValidated(track, aid)
end)

---Process validated animation track.
---@param self AnimatorDefender
---@param track AnimationTrack
---@param aid string
---@param gateDelay number? Extra delay from ramp gate to compensate in timing.
AnimatorDefender.processValidated = LPH_NO_VIRTUALIZE(function(self, track, aid, gateDelay)
	---@type AnimationTiming?
	local timing = self:initial(self.entity, SaveManager.as, self.entity.Name, aid)

	---@note: Record playback data for visualizer/builder regardless of existing timing.
	if Configuration.expectToggleValue("ShowAnimationVisualizer") then
		self.pbdata[track] = PlaybackData.new(self.entity)
	end

	if not timing then
		return
	end

	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return
	end

	local humanoidRootPart = self.entity:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if timing.tag == "Critical" then
		timing.nbfb = true
		timing.ha = true
	end

	---@note: Clean up previous tasks that are still waiting or suspended because they're in a different track.
	self:clean()

	-- Set current data.
	self.timing = timing
	self.track = track
	self.offset = Latency.rdelay() + (gateDelay or 0)

	self._trackSeq = self._trackSeq + 1
	local mySeq = self._trackSeq

	-- Post-check protection for player entities.
	if Configuration.expectToggleValue("ValidateIncomingAnimations") then
		local isPlayer = players:GetPlayerFromCharacter(self.entity)
		if isPlayer then
			-- Ramp check: reject flat/de-weighted animations that passed the 0.02s gate.
			task.spawn(function()
				task.wait(0.08)

				if self._trackSeq ~= mySeq then
					return
				end

				local killed = not track.IsPlaying and track.TimePosition < track.Length
				local flatWeight = track.IsPlaying and track.WeightCurrent < 0.50

				if killed or flatWeight then
					Logger.warn(
						"(%s) Animation from %s failed ramp check. (IsPlaying=%s, WC=%.4f, TimePos=%.3f at ~0.08s)",
						track.Animation.AnimationId,
						self.entity.Name,
						tostring(track.IsPlaying),
						track.WeightCurrent,
						track.TimePosition
					)
					self:clean()
				end
			end)

			-- Secondary check: full validation at 0.25s.
			task.spawn(function()
				task.wait(0.25)

				if self._trackSeq ~= mySeq then
					return
				end

				local killed = not track.IsPlaying and track.TimePosition < track.Length
				local deweighted = track.IsPlaying and track.WeightCurrent < 0.20

				if killed or deweighted then
					Logger.warn(
						"(%s) Animation from %s manipulated post-check. (IsPlaying=%s, WC=%.4f, Speed=%.2f, TimePos=%.3f, Length=%.3f)",
						track.Animation.AnimationId,
						self.entity.Name,
						tostring(track.IsPlaying),
						track.WeightCurrent,
						track.Speed,
						track.TimePosition,
						track.Length
					)
					self:clean()
				end
			end)
		end
	end

	-- Use module over actions.
	if timing.umoa then
		return self:module(timing)
	end

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not timing.rpue then
		return self:actions(timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
	info.track = track
	self:srpue(self.entity, timing, info)
end)

---Clean up the defender.
function AnimatorDefender:clean()
	-- Empty data.
	self.keyframes = {}

	-- Clean through base method.
	Defender.clean(self)
end

---Create new AnimatorDefender object.
---@param animator Animator
---@param manimations table<number, Animation>
---@return AnimatorDefender
function AnimatorDefender.new(animator, manimations)
	local entity = animator:FindFirstAncestorWhichIsA("Model")
	if not entity then
		return error(string.format("AnimatorDefender.new(%s) - no entity.", animator:GetFullName()))
	end

	local self = setmetatable(Defender.new(), AnimatorDefender)
	local animationPlayed = Signal.new(animator.AnimationPlayed)

	self.animator = animator
	self.manimations = manimations
	self.entity = entity

	self.track = nil
	self.timing = nil
	self.offset = nil

	self.keyframes = {}
	self.pbdata = {}
	self.rpbdata = {}
	self.sct = {}
	self.tsc = {}
	self.multiplier = {}

	-- Evaluation-data AP break state.
	self._evaluationData = {}

	-- AP break protection state.
	self._apbLowCount = 0
	self._apbLastLow = 0
	self._apbFlagged = false
	self._apbFlaggedAt = 0
	self._apbAnimTimestamps = {}
	self._apbSamples = {}
	self._apbProfile = nil

	-- FIX: Monotonic sequence counter. Starts at 0; incremented each time self.track
	-- is assigned in processValidated. Deferred tasks capture this value at spawn time
	-- and compare it at execution time — if it has changed, a newer track has taken
	-- over and the callback should not clean() the current state.
	self._trackSeq = 0

	self.maid:mark(animationPlayed:connect(
		"AnimatorDefender_OnAnimationPlayed",
		LPH_NO_VIRTUALIZE(function(track)
			self:process(track)
		end)
	))

	return self
end

-- Return AnimatorDefender module.
return AnimatorDefender
end)
__bundle_register("Game/Timings/PlaybackData", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class PlaybackData
---@field base number Timestamp of when the object was created.
---@field ash table<number, number> Animation speed history. The key is the timestamp delta and the value is the speed at that point.
---@field entity Model Entity to playback.
local PlaybackData = {}
PlaybackData.__index = PlaybackData

---Get last exceeded speed difference from a timestamp delta.
---@param from number
---@return number?, number?
function PlaybackData:last(from)
	local latestExceededSpeed = nil
	local latestExceededDelta = nil

	for delta, speed in next, self.ash do
		if from <= delta then
			continue
		end

		if latestExceededDelta and delta <= latestExceededDelta then
			continue
		end

		latestExceededSpeed = speed
		latestExceededDelta = delta
	end

	return latestExceededSpeed, latestExceededDelta
end

---Track animation speed.
---@param speed number
function PlaybackData:astrack(speed)
	local delta = os.clock() - self.base

	if self:last(delta) == speed then
		return
	end

	self.ash[delta] = speed
end

---Create new PlaybackData object.
---@param entity Model
---@return PlaybackData
function PlaybackData.new(entity)
	local self = setmetatable({}, PlaybackData)
	self.base = os.clock()
	self.entity = entity

	---@note: Timestamp delta is how many seconds need to pass before being able to reach this speed.
	self.ash = {}

	return self
end

-- Return PlaybackData module.
return PlaybackData

end)
__bundle_register("Utility/ControlModule", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	-- This module is used for getting the proper input fly values - 1:1 with Aztup.
	local ControlModule = {
		forwardValue = 0,
		backwardValue = 0,
		leftValue = 0,
		rightValue = 0,
	}

	---@module Utility.Profiler
	local Profiler = require("Utility/Profiler")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	-- Maids.
	local controlMaid = Maid.new()

	-- Services.
	local ContextActionService = game:GetService("ContextActionService")

	---Bind action safely with maid, error, and profiler handling.
	---@param actionName string
	---@param callback function
	---@param createTouchButton boolean
	local function bindActionWrapper(actionName, callback, createTouchButton, ...)
		---Log bind action errors.
		---@param error string
		local function onBindActionWrapperError(error)
			Logger.trace("onBindActionWrapperError - (%s) - %s", actionName, error)
		end

		local actionWrapperCallback = callback
			and Profiler.wrap(string.format("ControlModule_BindActionWrapper_%s", actionName), function(...)
				local success, result = xpcall(callback, onBindActionWrapperError, ...)

				if not success then
					return nil
				end

				return result
			end)

		---@note: This is a hot-fix and should be handled properly in the future.
		controlMaid:add(function()
			ContextActionService:UnbindAction(actionName)
		end)

		ContextActionService:BindAction(actionName, actionWrapperCallback, createTouchButton, ...)
	end

	---Initialize control module.
	function ControlModule.init()
		bindActionWrapper("ControlModule_ForwardValue", function(_, inputState, _)
			ControlModule.forwardValue = (inputState == Enum.UserInputState.Begin) and -1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.W)

		bindActionWrapper("ControlModule_LeftValue", function(_, inputState, _)
			ControlModule.leftValue = (inputState == Enum.UserInputState.Begin) and -1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.A)

		bindActionWrapper("ControlModule_BackwardValue", function(_, inputState, _)
			ControlModule.backwardValue = (inputState == Enum.UserInputState.Begin) and 1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.S)

		bindActionWrapper("ControlModule_RightValue", function(_, inputState, _)
			ControlModule.rightValue = (inputState == Enum.UserInputState.Begin) and 1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.D)

		Logger.warn("ControlModule initialized.")
	end

	---Detach control module.
	function ControlModule.detach()
		controlMaid:clean()
		Logger.warn("ControlModule detached.")
	end

	---Get move vector.
	---@return Vector3
	function ControlModule.getMoveVector()
		return Vector3.new(
			ControlModule.leftValue + ControlModule.rightValue,
			0,
			ControlModule.forwardValue + ControlModule.backwardValue
		)
	end

	-- Return control module.
	return ControlModule
end)()

end)
