---Initialize World Visuals section.
---@param groupbox table
function VisualsTab.initWorldVisualsSection(groupbox)
	groupbox:AddButton("Use Fast Flags For Session", function()
		local success, content = pcall(readfile, "fflags.txt")
		if not success then
			return Logger.longNotify("Failed to load fflags.txt. Make sure the file exists in your workspace.")
		end
		local decodeSuccess, fflags = pcall(game:GetService("HttpService").JSONDecode, game:GetService("HttpService"), content)
		if not decodeSuccess then
			return Logger.longNotify("fflags.txt is not a valid JSON format.")
		end
		for index, value in next, fflags do
			pcall(function()
				setfflag(index, tostring(value))
			end)
		end
		Logger.notify("Fast Flags applied successfully for this session server hop to see changes.")
	end)

	groupbox:AddButton("Show All on Map", function()
		local modules = game:GetService("ReplicatedStorage"):FindFirstChild("Modules")
		local reputation_system_mod = modules and modules:FindFirstChild("ReputationSystem")
		
		if not reputation_system_mod then 
			return Logger.longNotify("ReputationSystem module not found.") 
		end
		local reputation_system = require(reputation_system_mod)
		_G.old_is_ally = hookfunction(reputation_system.IsAlly, function(...)
			local calling_script = getcallingscript()
			if calling_script and calling_script.Name == "MapClient" then
				return true
			end
			
			return _G.old_is_ally(...)
		end)
		local character = game:GetService("Players").LocalPlayer.Character
		if character then
			local old_guild = character:GetAttribute("Guild")
			if old_guild then
				character:SetAttribute("Guild", old_guild .. " ")
				character:SetAttribute("Guild", old_guild)
			end
		end

		Logger.notify("Show All Players logic applied to Map.")
	end)

	groupbox:AddToggle("ModifyFieldOfView", {
		Text = "Modify Field Of View",
		Default = false,
	})

	local fovDepBox = groupbox:AddDependencyBox()

	fovDepBox:AddSlider("FieldOfView", {
		Text = "Field Of View Slider",
		Default = 90,
		Min = 0,
		Max = 120,
		Suffix = "°",
		Rounding = 0,
	})

	fovDepBox:SetupDependencies({
		{ Toggles.ModifyFieldOfView, true },
	})

	local modifyAmbienceToggle = groupbox:AddToggle("ModifyAmbience", {
		Text = "Modify Ambience",
		Tooltip = "Modify the ambience of the game.",
		Default = false,
	})

	modifyAmbienceToggle:AddColorPicker("AmbienceColor", {
		Default = Color3.fromHex("FFFFFF"),
	})

	local oacDepBox = groupbox:AddDependencyBox()

